function 시뮬(횟수 = 100000) {
  let 합 = 0; const 표본 = [];
  for (let i = 0; i < 횟수; i++) {
    const d = Math.random() < 0.2 ? 200 : 100;
    합 += d; 표본.push(d);
  }
  표본.sort((a, b) => a - b);
  return { 평균: 합 / 횟수, p10: 표본[횟수 * 0.1 | 0], p90: 표본[횟수 * 0.9 | 0] };
}
// 수식을 못 세워도 10만 번 돌리면 답이 나온다  ★ 밸런스 작업의 기본기
